"use strict";(globalThis.webpackChunklearnalgorithms=globalThis.webpackChunklearnalgorithms||[]).push([[3684],{9215(e){e.exports=JSON.parse('{"tag":{"label":"Master Theorem","permalink":"/concepts/tags/master-theorem","allTagsPath":"/concepts/tags","count":1,"items":[{"id":"algorithm-design-paradigms/divide-and-conquer-analysis","title":"Analyzing Divide and Conquer","description":"The loops of iterative algorithms can be analyzed by counting iterations, as we did in the first chapter. Recursive algorithms need a different tool: the execution time is expressed in terms of itself applied to smaller sizes, giving a recurrence equation. Fortunately, most divide and conquer algorithms follow one of two very regular patterns, and for both of them the solution is known in general. This lesson presents those two patterns, explains where their formulas come from, and shows how to apply them.","permalink":"/concepts/algorithm-design-paradigms/divide-and-conquer-analysis"}],"unlisted":false}}')}}]);